package deployer_test

import (
	"context"
	"testing"
	"time"

	"github.com/nlewo/comin/internal/broker"
	"github.com/nlewo/comin/internal/deployer"
	"github.com/nlewo/comin/internal/protobuf"
	"github.com/nlewo/comin/internal/store"
	"github.com/stretchr/testify/assert"
)

func TestDeployerBasic(t *testing.T) {
	deployDone := make(chan struct{})
	var deployFunc = func(context.Context, string, string, []string) (bool, string, error) {
		<-deployDone
		return false, "profile-path", nil
	}

	tmp := t.TempDir()
	bk := broker.New()
	bk.Start()

	s, err := store.New(bk, tmp+"/state.json", tmp+"/gcroots", 1, 1, 1)
	assert.Nil(t, err)
	d := deployer.New(s, deployFunc, nil, "")
	d.Run(t.Context())
	assert.False(t, d.IsDeploying())

	g := &protobuf.Generation{SelectedCommitId: "commit-1"}
	d.Submit(g, "test")
	assert.EventuallyWithT(t, func(c *assert.CollectT) {
		assert.True(c, d.IsDeploying())
	}, 5*time.Second, 100*time.Millisecond)

	deployDone <- struct{}{}
	assert.EventuallyWithT(t, func(c *assert.CollectT) {
		assert.False(c, d.IsDeploying())
		assert.Equal(c, "profile-path", d.Deployment().ProfilePath)
	}, 5*time.Second, 100*time.Millisecond)

	assert.EventuallyWithT(t, func(c *assert.CollectT) {
		dpl := <-d.DeploymentDoneCh
		assert.Equal(c, "profile-path", dpl.ProfilePath)
		assert.Equal(c, "commit-1", dpl.Generation.SelectedCommitId)
	}, 5*time.Second, 100*time.Millisecond)
}

func TestDeployerSubmit(t *testing.T) {
	deployDone := make(chan struct{})
	var deployFunc = func(context.Context, string, string, []string) (bool, string, error) {
		<-deployDone
		return false, "profile-path", nil
	}

	tmp := t.TempDir()
	bk := broker.New()
	bk.Start()

	s, err := store.New(bk, tmp+"/state.json", tmp+"/gcroots", 1, 1, 1)
	assert.Nil(t, err)
	d := deployer.New(s, deployFunc, nil, "")
	d.Run(t.Context())
	assert.False(t, d.IsDeploying())

	d.Submit(&protobuf.Generation{SelectedCommitId: "commit-1"}, "test")
	assert.EventuallyWithT(t, func(c *assert.CollectT) {
		assert.True(c, d.IsDeploying())
		assert.Nil(c, d.GenerationToDeploy)
	}, 5*time.Second, 100*time.Millisecond)

	d.Submit(&protobuf.Generation{SelectedCommitId: "commit-2"}, "test")
	d.Submit(&protobuf.Generation{SelectedCommitId: "commit-3"}, "test")
	assert.NotNil(t, d.GenerationToDeploy)

	// To simulate the end of 2 deployments (commit-1 and commit-3)
	deployDone <- struct{}{}
	deployDone <- struct{}{}
	assert.EventuallyWithT(t, func(c *assert.CollectT) {
		assert.False(c, d.IsDeploying())
		assert.Equal(c, "profile-path", d.Deployment().ProfilePath)
		assert.Nil(t, d.GenerationToDeploy)
	}, 5*time.Second, 100*time.Millisecond)

	assert.EventuallyWithT(t, func(c *assert.CollectT) {
		dpl := <-d.DeploymentDoneCh
		assert.Equal(c, "profile-path", dpl.ProfilePath)
		assert.Equal(c, "commit-1", dpl.Generation.SelectedCommitId)
	}, 5*time.Second, 100*time.Millisecond)
}

func TestDeployerSuspend(t *testing.T) {
	deployDone := make(chan struct{})
	var deployFunc = func(context.Context, string, string, []string) (bool, string, error) {
		<-deployDone
		return false, "profile-path", nil
	}

	tmp := t.TempDir()
	bk := broker.New()
	bk.Start()

	s, err := store.New(bk, tmp+"/state.json", tmp+"/gcroots", 1, 1, 1)
	assert.Nil(t, err)
	d := deployer.New(s, deployFunc, nil, "")
	d.Run(t.Context())
	assert.False(t, d.IsSuspended())
	d.Suspend()
	assert.True(t, d.IsSuspended())
	assert.False(t, d.IsDeploying())
	assert.False(t, d.RunnerIsSuspended())

	d.Submit(&protobuf.Generation{SelectedCommitId: "commit-1"}, "test")
	assert.EventuallyWithT(t, func(c *assert.CollectT) {
		assert.True(t, d.RunnerIsSuspended())
	}, 3*time.Second, 100*time.Millisecond)

	d.Resume()
	assert.EventuallyWithT(t, func(c *assert.CollectT) {
		assert.False(t, d.RunnerIsSuspended())
		assert.True(t, d.IsDeploying())
	}, 3*time.Second, 100*time.Millisecond)
}

## Authentication for private repositories

### GitLab

You need to create a [personal access
token](https://docs.gitlab.com/ee/user/profile/personal_access_tokens.html) with the `read_repository` scope
and store this token into a file (`/filepath/to/your/access/token` in the below example). 

### GitHub

You need to create a [fined-grained personal access
token](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens#fine-grained-personal-access-tokens)
and store this token into a file (`/filepath/to/your/access/token` in
the below example). Note classic personal access tokens are also
supported.

### Use your personal access token

The file path containing this access token for a remote is provided
with the attribute `comin.remotes.*.auth.access_token_path`.

#### Example

```nix
services.comin = {
  enable = true;
  remotes = [
    {
      name = "origin";
      url = "https://gitlab.com/your/private-infra.git";
      auth.access_token_path = "/filepath/to/your/access/token";
    }
  ];
};
```

package cmd

import (
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/nlewo/comin/internal/client"
	"github.com/nlewo/comin/internal/protobuf"
	"github.com/sirupsen/logrus"
	"github.com/spf13/cobra"
)

var deploymentCmd = &cobra.Command{
	Use: "deployment",
}

var bootOnly bool

var deploymentListCmd = &cobra.Command{
	Use:  "list",
	Args: cobra.MinimumNArgs(0),
	Run: func(cmd *cobra.Command, args []string) {
		opts := client.ClientOpts{
			UnixSocketPath: "/var/lib/comin/grpc.sock",
		}
		c, err := client.New(opts)
		if err != nil {
			logrus.Fatal(err)
		}
		status, err := c.GetManagerState()
		if err != nil {
			logrus.Fatal(err)
		}
		dpls := status.Store.Deployments
		if bootOnly {
			dpls = filterBootEntryDeployments(dpls, status.Store)
		}
		deploymentList(dpls, status.Store, bootOnly)
	},
}

var deploymentSwitchLatestCmd = &cobra.Command{
	Use:  "switch-latest",
	Args: cobra.MinimumNArgs(0),
	Run: func(cmd *cobra.Command, args []string) {
		opts := client.ClientOpts{
			UnixSocketPath: "/var/lib/comin/grpc.sock",
		}
		c, err := client.New(opts)
		if err != nil {
			logrus.Fatal(err)
		}
		err = c.SwitchDeploymentLatest()
		if err != nil {
			logrus.Fatal(err)
		}
	},
}

func retentionListsForDeployment(uuid string, store *protobuf.Store) (result []string) {
	if store.DeploymentSwitched == uuid {
		result = append(result, "switched")
	}
	if store.DeploymentBooted == uuid {
		result = append(result, "booted")
	}
	if slices.Contains(store.DeploymentsBootEntry, uuid) {
		result = append(result, "boot")
	}
	if slices.Contains(store.DeploymentsSuccessful, uuid) {
		result = append(result, "successful")
	}
	if slices.Contains(store.DeploymentsAny, uuid) {
		result = append(result, "any")
	}
	return
}

func filterBootEntryDeployments(dpls []*protobuf.Deployment, store *protobuf.Store) []*protobuf.Deployment {
	bootUUIDs := make(map[string]struct{})
	if store.DeploymentSwitched != "" {
		bootUUIDs[store.DeploymentSwitched] = struct{}{}
	}
	if store.DeploymentBooted != "" {
		bootUUIDs[store.DeploymentBooted] = struct{}{}
	}
	for _, uuid := range store.DeploymentsBootEntry {
		bootUUIDs[uuid] = struct{}{}
	}
	var filtered []*protobuf.Deployment
	for _, dpl := range dpls {
		if _, ok := bootUUIDs[dpl.Uuid]; ok {
			filtered = append(filtered, dpl)
		}
	}
	return filtered
}

func deploymentList(dpls []*protobuf.Deployment, store *protobuf.Store, newestFirst bool) {
	endedAtCmp := func(a, b *protobuf.Deployment) int {
		return a.EndedAt.AsTime().Compare(b.EndedAt.AsTime())
	}
	slices.SortFunc(dpls, endedAtCmp)
	if newestFirst {
		slices.Reverse(dpls)
	}

	for _, dpl := range dpls {
		fmt.Printf("%s\n", dpl.Uuid)
		fmt.Printf("  status             %s\n", dpl.Status)
		fmt.Printf("  ended at           %s\n", dpl.EndedAt.AsTime().Format(time.DateTime))
		fmt.Printf("  operation          %s\n", dpl.Operation)
		if dpl.ProfilePath != "" {
			fmt.Printf("  profile path       %s\n", dpl.ProfilePath)
		}
		fmt.Printf("  out path           %s\n", dpl.Generation.OutPath)
		fmt.Printf("  generation uuid    %s\n", dpl.Generation.Uuid)
		fmt.Printf("    commit id        %s\n", dpl.Generation.SelectedCommitId)
		if lists := retentionListsForDeployment(dpl.Uuid, store); len(lists) > 0 {
			fmt.Printf("  part of retention  %s\n", strings.Join(lists, ", "))
		}
		fmt.Print("\n")
	}
}

func init() {
	rootCmd.AddCommand(deploymentCmd)
	deploymentCmd.AddCommand(deploymentListCmd)
	deploymentListCmd.Flags().BoolVar(&bootOnly, "boot", false, "only show boot entry deployments, newest first")
	deploymentCmd.AddCommand(deploymentSwitchLatestCmd)
}

package store

import (
	"fmt"
	"maps"
	"slices"
	"time"

	"github.com/google/uuid"
	"github.com/nlewo/comin/internal/protobuf"
	"github.com/sirupsen/logrus"
	"google.golang.org/protobuf/types/known/timestamppb"
	"google.golang.org/protobuf/types/known/wrapperspb"
)

type Status int64

const (
	Init Status = iota
	Running
	Done
	Failed
)

func StatusToString(status Status) string {
	switch status {
	case Init:
		return "init"
	case Running:
		return "running"
	case Done:
		return "done"
	case Failed:
		return "failed"
	}
	return ""
}

func StringToStatus(statusStr string) Status {
	switch statusStr {
	case "init":
		return Init
	case "running":
		return Running
	case "done":
		return Done
	case "failed":
		return Failed
	}
	return Init
}

func IsTesting(d *protobuf.Deployment) bool {
	return d.Operation == "test"
}

func logDiff(name string, old, new []string) {
	for _, o := range old {
		if !slices.Contains(new, o) {
			logrus.Infof("store: removing from the list '%s' the deployment of %s ", name, o)
		}
	}
	for _, n := range new {
		if !slices.Contains(old, n) {
			logrus.Infof("store: adding to the list '%s' the deployment %s", name, n)
		}
	}
}

// updateDataDeployments is not thread safe
func (s *Store) updateDataDeployments(bootedStorepath, currentStorepath string, new *protobuf.Deployment) {
	current, booted, bootEntries, successful, any := retention(s.data.Deployments, new, bootedStorepath, currentStorepath, s.bootEntryCapacity, s.successfulCapacity, s.anyCapacity)

	if current != s.data.DeploymentSwitched {
		logrus.Infof("store: retention: the current deployment has been updated from %s to %s", s.data.DeploymentSwitched, current)
		s.data.DeploymentSwitched = current
	}
	if booted != s.data.DeploymentBooted {
		logrus.Infof("store: retention: the booted deployment has been updated from %s to %s", s.data.DeploymentSwitched, current)
		s.data.DeploymentBooted = booted
	}
	logDiff("boot entries", s.data.DeploymentsBootEntry, bootEntries)
	s.data.DeploymentsBootEntry = bootEntries

	logDiff("deployments successful", s.data.DeploymentsSuccessful, successful)
	s.data.DeploymentsSuccessful = successful

	logDiff("any deployments", s.data.DeploymentsAny, any)
	s.data.DeploymentsAny = any

	dpls := s.data.Deployments
	if new != nil {
		dpls = append(s.data.Deployments, new)
	}
	allUuids := []string{}
	for _, uuid := range slices.Concat([]string{current, booted}, s.data.DeploymentsBootEntry, s.data.DeploymentsSuccessful, s.data.DeploymentsAny) {
		if !slices.Contains(allUuids, uuid) {
			allUuids = append(allUuids, uuid)
		}
	}
	acc := make([]*protobuf.Deployment, 0)
	for _, d := range dpls {
		if slices.Contains(allUuids, d.Uuid) && !slices.ContainsFunc(acc, func(a *protobuf.Deployment) bool { return a.Uuid == d.Uuid }) {
			acc = append(acc, d)
		}
	}
	endedAtCmp := func(a, b *protobuf.Deployment) int {
		return -a.CreatedAt.AsTime().Compare(b.CreatedAt.AsTime())
	}
	slices.SortFunc(acc, endedAtCmp)

	s.data.Deployments = acc
	s.Commit()
}

func (s *Store) NewDeployment(g *protobuf.Generation, operation, reason, bootedStorepath, currentStorepath string) *protobuf.Deployment {
	s.mu.Lock()
	defer s.mu.Unlock()
	d := &protobuf.Deployment{
		Uuid:       uuid.New().String(),
		Generation: g,
		Operation:  operation,
		Reason:     reason,
		Status:     StatusToString(Init),
		CreatedAt:  timestamppb.New(time.Now().UTC()),
	}
	s.updateDataDeployments(bootedStorepath, currentStorepath, d)
	s.Commit()
	return d

}

func (s *Store) deploymentGet(uuid string) (g *protobuf.Deployment, err error) {
	for _, d := range s.data.Deployments {
		if d.Uuid == uuid {
			return d, nil
		}
	}
	return nil, fmt.Errorf("store: no deployment with uuid %s has been found", uuid)
}

func (s *Store) GetDeploymentLastest() (latest *protobuf.Deployment) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, d := range s.data.Deployments {
		if latest == nil || d.EndedAt != nil && d.CreatedAt.AsTime().After(latest.CreatedAt.AsTime()) {
			latest = d
		}
	}
	return
}

func (s *Store) GetDeploymentProfilePaths() []string {
	m := make(map[string]struct{})
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, d := range s.data.Deployments {
		if d.ProfilePath != "" {
			m[d.ProfilePath] = struct{}{}
		}
	}
	return slices.Collect(maps.Keys(m))
}

func (s *Store) DeploymentStarted(uuid, bootedStorepath, currentStorepath string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	d, err := s.deploymentGet(uuid)
	if err != nil {
		return err
	}
	d.StartedAt = timestamppb.New(time.Now().UTC())
	d.Status = StatusToString(Running)
	e := &protobuf.Event_DeploymentStarted{Deployment: d}
	s.broker.Publish(&protobuf.Event{Type: &protobuf.Event_DeploymentStartedType{DeploymentStartedType: e}})
	s.updateDataDeployments(bootedStorepath, currentStorepath, d)
	return nil
}

func (s *Store) DeploymentFinished(uuid string, deploymentErr error, cominNeedRestart bool, profilePath string, bootedStorepath, currentStorepath string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	d, err := s.deploymentGet(uuid)
	if err != nil {
		return err
	}
	if deploymentErr != nil {
		d.ErrorMsg = deploymentErr.Error()
		d.Status = StatusToString(Failed)
	} else {
		d.Status = StatusToString(Done)
	}
	d.EndedAt = timestamppb.New(time.Now().UTC())
	d.Status = StatusToString(Done)
	d.RestartComin = wrapperspb.Bool(cominNeedRestart)
	d.ProfilePath = profilePath
	e := &protobuf.Event_DeploymentFinished{Deployment: d}
	s.broker.Publish(&protobuf.Event{Type: &protobuf.Event_DeploymentFinishedType{DeploymentFinishedType: e}})
	s.updateDataDeployments(bootedStorepath, currentStorepath, d)
	return nil
}

func isBootEntry(d *protobuf.Deployment) bool {
	return d.Operation == "boot" || d.Operation == "switch"
}

func retention(dpls []*protobuf.Deployment, new *protobuf.Deployment, bootedStorepath, switchedStorepath string, bootEntryCapacity, successfulCapacity, allCapacity int) (string, string, []string, []string, []string) {
	var current, booted string
	deploymentsBootEntry := make([]string, 0)
	deploymentsSuccessful := make([]string, 0)
	deploymentsAny := make([]string, 0)

	if new != nil {
		dpls = append(dpls, new)
	}

	// Sort deployments from newer to older
	endedAtCmp := func(a, b *protobuf.Deployment) int {
		return -a.CreatedAt.AsTime().Compare(b.CreatedAt.AsTime())
	}
	slices.SortFunc(dpls, endedAtCmp)

	// 1. Always keep the current booted system
	for _, d := range dpls {
		if isBootEntry(d) && d.Status == "done" && d.Generation.OutPath == bootedStorepath {
			booted = d.Uuid
			break
		}
	}

	// 2. Always keep the current switched system
	for _, d := range dpls {
		if d.Operation == "switch" && d.Status == "done" && d.Generation.OutPath == switchedStorepath {
			current = d.Uuid
			break
		}
	}

	// 3. Boot entries with storepath deduplication
	storepaths := make(map[string]struct{})
	for _, d := range dpls {
		if len(storepaths) >= bootEntryCapacity {
			break
		}
		if !isBootEntry(d) || d.Status != "done" {
			continue
		}
		if _, exists := storepaths[d.Generation.OutPath]; exists {
			continue
		}
		storepaths[d.Generation.OutPath] = struct{}{}
		deploymentsBootEntry = append(deploymentsBootEntry, d.Uuid)
	}

	// 4. Successful deployments (any operation)
	counter := 0
	for _, d := range dpls {
		if d.Status != "done" {
			continue
		}
		if counter >= successfulCapacity {
			break
		}
		counter++
		deploymentsSuccessful = append(deploymentsSuccessful, d.Uuid)
	}

	// 5. All deployments (any status)
	counter = 0
	for _, d := range dpls {
		if counter >= allCapacity {
			break
		}
		counter++
		deploymentsAny = append(deploymentsAny, d.Uuid)
	}

	return current, booted, deploymentsBootEntry, deploymentsSuccessful, deploymentsAny
}

package deployer

import (
	"fmt"
	"os"
	"os/exec"
	"strings"

	pb "github.com/nlewo/comin/internal/protobuf"

	"github.com/sirupsen/logrus"
)

func envGitSha(d *pb.Deployment) string {
	return d.Generation.SelectedCommitId
}

func envGitRef(d *pb.Deployment) string {
	return fmt.Sprintf("%s/%s", d.Generation.SelectedRemoteName, d.Generation.SelectedBranchName)
}

func envGitMessage(d *pb.Deployment) string {
	return strings.Trim(d.Generation.SelectedCommitMsg, "\n")
}

func envCominGeneration(d *pb.Deployment) string {
	return d.Generation.Uuid
}

func envCominHostname(d *pb.Deployment) string {
	return d.Generation.Hostname
}

func envCominStatus(d *pb.Deployment) string {
	return d.Status
}

func envCominErrorMessage(d *pb.Deployment) string {
	return d.ErrorMsg
}

func runPostDeploymentCommand(command string, d *pb.Deployment) (string, error) {

	cmd := exec.Command(command)

	cmd.Env = append(os.Environ(),
		"COMIN_GIT_SHA="+envGitSha(d),
		"COMIN_GIT_REF="+envGitRef(d),
		"COMIN_GIT_MSG="+envGitMessage(d),
		"COMIN_HOSTNAME="+envCominHostname(d),
		"COMIN_GENERATION="+envCominGeneration(d),
		"COMIN_STATUS="+envCominStatus(d),
		"COMIN_ERROR_MSG="+envCominErrorMessage(d),
	)

	output, err := cmd.CombinedOutput()
	outputString := string(output)
	if err != nil {
		return outputString, err
	}

	logrus.Debugf("cmd:[%s] output:[%s]", command, outputString)

	return outputString, nil
}

package deployer

import (
	"context"
	"fmt"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/dustin/go-humanize"
	"github.com/nlewo/comin/internal/protobuf"
	"github.com/nlewo/comin/internal/store"
	"github.com/nlewo/comin/internal/utils"
	"github.com/sirupsen/logrus"
	"google.golang.org/protobuf/types/known/timestamppb"
	"google.golang.org/protobuf/types/known/wrapperspb"
)

const (
	ReasonDeploymentBuilder = "builder"
	ReasonDeploymentManual  = "manual"
)

type DeployFunc func(context.Context, string, string, []string) (bool, string, error)

type Deployer struct {
	GenerationCh       chan *protobuf.Generation
	deployerFunc       DeployFunc
	DeploymentDoneCh   chan *protobuf.Deployment
	mu                 sync.Mutex
	deployment         atomic.Pointer[protobuf.Deployment]
	previousDeployment atomic.Pointer[protobuf.Deployment]
	isDeploying        atomic.Bool
	// The next generation to deploy. nil when there is no new generation to deploy
	GenerationToDeploy *protobuf.Generation
	// The operation to use for the next deployment
	Operation string
	// Reason is the reason of the next deployment
	Reason                string
	generationAvailableCh chan struct{}
	postDeploymentCommand string

	isSuspended atomic.Bool
	resumeCh    chan struct{}
	// This is true when the runner is actually suspended. This is
	// mainly used for testing purpose.
	runnerIsSuspended atomic.Bool
	store             *store.Store
}

func (d *Deployer) State() *protobuf.Deployer {
	d.mu.Lock()
	defer d.mu.Unlock()
	return &protobuf.Deployer{
		IsDeploying:        wrapperspb.Bool(d.isDeploying.Load()),
		GenerationToDeploy: d.GenerationToDeploy,
		Operation:          d.Operation,
		Deployment:         d.deployment.Load(),
		PreviousDeployment: d.previousDeployment.Load(),
		IsSuspended:        wrapperspb.Bool(d.isSuspended.Load()),
	}
}

func (d *Deployer) Deployment() *protobuf.Deployment {
	return d.deployment.Load()
}

func (d *Deployer) IsDeploying() bool {
	return d.isDeploying.Load()
}

func (d *Deployer) RunnerIsSuspended() bool {
	return d.runnerIsSuspended.Load()
}

func (d *Deployer) IsSuspended() bool {
	return d.isSuspended.Load()
}

func showDeployment(padding string, d *protobuf.Deployment) {
	switch d.Status {
	case store.StatusToString(store.Running):
		fmt.Printf("%sDeployment is running since %s\n", padding, humanize.Time(d.StartedAt.AsTime()))
		fmt.Printf("%sOperation %s\n", padding, d.Operation)
	case store.StatusToString(store.Done):
		fmt.Printf("%sDeployment succeeded %s\n", padding, humanize.Time(d.EndedAt.AsTime()))
		fmt.Printf("%sOperation %s\n", padding, d.Operation)
		fmt.Printf("%sProfilePath %s\n", padding, d.ProfilePath)
	case store.StatusToString(store.Failed):
		fmt.Printf("%sDeployment failed %s\n", padding, humanize.Time(d.EndedAt.AsTime()))
		fmt.Printf("%sOperation %s\n", padding, d.Operation)
		fmt.Printf("%sProfilePath %s\n", padding, d.ProfilePath)
	}
	fmt.Printf("%sGeneration %s\n", padding, d.Generation.Uuid)
	fmt.Printf("%sCommit ID %s from %s/%s\n", padding, d.Generation.SelectedCommitId, d.Generation.SelectedRemoteName, d.Generation.SelectedBranchName)
	fmt.Printf("%sCommit message %s\n", padding, strings.Trim(d.Generation.SelectedCommitMsg, "\n"))
	fmt.Printf("%sOutpath %s\n", padding, d.Generation.OutPath)
}

func Show(s *protobuf.Deployer, padding string) {
	fmt.Printf("  Deployer\n")
	if s.Deployment == nil {
		if s.PreviousDeployment == nil {
			fmt.Printf("%sNo deployment yet\n", padding)
			return
		}
		showDeployment(padding, s.PreviousDeployment)
		return
	}
	showDeployment(padding, s.Deployment)
}

func New(store *store.Store, deployFunc DeployFunc, previousDeployment *protobuf.Deployment, postDeploymentCommand string) *Deployer {
	if previousDeployment != nil {
		logrus.Infof("deployer: initializing with previous deployment %s", previousDeployment.Uuid)
	}
	deployer := &Deployer{
		store:                 store,
		DeploymentDoneCh:      make(chan *protobuf.Deployment, 1),
		deployerFunc:          deployFunc,
		generationAvailableCh: make(chan struct{}, 1),
		postDeploymentCommand: postDeploymentCommand,

		resumeCh: make(chan struct{}, 1),
	}
	deployer.previousDeployment.Store(previousDeployment)
	deployer.deployment.Store(previousDeployment)

	return deployer
}

func (d *Deployer) Suspend() {
	d.isSuspended.Store(true)
}

func (d *Deployer) Resume() {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.isSuspended.Store(false)
	select {
	case d.resumeCh <- struct{}{}:
	default:
	}
}

func (d *Deployer) IsAlreadyDeployed(generation *protobuf.Generation, operation string) bool {
	previous := d.previousDeployment.Load()
	if previous == nil {
		logrus.Infof("deployer: no previous deployment found for generation %s", generation.Uuid)
		return false
	}
	if generation.OutPath != previous.Generation.OutPath {
		logrus.Infof("deployer: out path %s differs from previous out path %s for generation %s", generation.OutPath, previous.Generation.OutPath, generation.Uuid)
		return false
	}
	if previous.Operation != operation {
		logrus.Infof("deployer: operation %s differs from previous operation %s for generation %s", operation, previous.Operation, generation.Uuid)
		return false
	}
	logrus.Infof("deployer: skipping deployment of generation %s: out path %s with operation %s has already been deployed", generation.Uuid, generation.OutPath, operation)
	return true
}

// Submit submits a generation to be deployed. If a deployment is
// running, this generation will be deployed once the current
// deployment is finished. If this generation is the same than the one
// of the last deployment, this generation is skipped.
func (d *Deployer) Submit(generation *protobuf.Generation, operation string) {
	logrus.Infof("deployer: submitting generation %s with operation %s", generation.Uuid, operation)
	d.mu.Lock()
	defer d.mu.Unlock()

	if !d.IsAlreadyDeployed(generation, operation) {
		d.GenerationToDeploy = generation
		d.Operation = operation
		select {
		case d.generationAvailableCh <- struct{}{}:
		default:
		}
	}
}

func (d *Deployer) Run(ctx context.Context) {
	go func() {
		for {
			<-d.generationAvailableCh

			if d.isSuspended.Load() {
				d.runnerIsSuspended.Store(true)
				<-d.resumeCh
				d.runnerIsSuspended.Store(false)
			}

			d.mu.Lock()
			g := d.GenerationToDeploy
			operation := d.Operation
			d.GenerationToDeploy = nil
			d.mu.Unlock()
			logrus.Infof("deployer: deploying generation %s with operation %s", g.Uuid, operation)
			booted, current := utils.GetBootedAndCurrentStorepaths()
			dpl := d.store.NewDeployment(g, d.Operation, d.Reason, booted, current)
			d.mu.Lock()
			d.previousDeployment.Swap(d.Deployment())
			d.deployment.Store(dpl)
			d.isDeploying.Store(true)
			d.mu.Unlock()
			if err := d.store.DeploymentStarted(dpl.Uuid, booted, current); err != nil {
				logrus.Errorf("deployer: could not update the deployment %s in the store", dpl.Uuid)
				continue
			}
			profilePaths := d.store.GetDeploymentProfilePaths()
			cominNeedRestart, profilePath, err := d.deployerFunc(
				ctx,
				g.OutPath,
				operation,
				profilePaths,
			)

			deployment := d.Deployment()
			deployment.EndedAt = timestamppb.New(time.Now().UTC())
			if err := d.store.DeploymentFinished(dpl.Uuid, err, cominNeedRestart, profilePath, booted, current); err != nil {
				logrus.Errorf("deployer: could not update the deployment %s in the store", dpl.Uuid)
				continue
			}
			cmd := d.postDeploymentCommand
			if cmd != "" {
				_, err = runPostDeploymentCommand(cmd, deployment)
				if err != nil {
					logrus.Errorf("deployer: deploying generation %s, post deployment command [%s] failed %v", g.Uuid, cmd, err)
				}
			}

			d.isDeploying.Store(false)
			d.deployment.Store(deployment)
			d.DeploymentDoneCh <- d.Deployment()
		}
	}()
}

# comin - GitOps for NixOS Machines

**comin** is a NixOS deployment tool operating in pull mode. Running
on a machine, it periodically polls Git repositories and deploys the
NixOS configuration associated to the machine.

## Features

- :snowflake: Git push to deploy NixOS configurations (or [nix-darwin](./docs/howtos.md#how-to-deploy-a-nix-darwin-configuration))
- :handshake: Support flake and [non-flake](./docs/howtos.md#how-to-use-comin-without-nix-flake) repositories
- :construction: Support testing branches to [try changes](./docs/howtos.md#how-to-test-a-nixos-configuration-change)
- :rocket: Poll [multiple Git remotes](./docs/generated-module-options.md#servicescominremotes) to avoid SPOF
- :postbox: Support [machines migrations](./docs/howtos.md#how-to-migrate-a-configuration-from-a-machine-to-another-one)
- :fast_forward: Fast iterations with [local remotes](./docs/howtos.md#iterate-faster-with-local-repository)
- :satellite: Observable via [Prometheus metrics](./docs/generated-module-options.md#servicescominexporter)
- :pushpin: Create and delete system profiles
- :lock: Optionally check [Git commit signatures](./docs/howtos.md#check-git-commit-signatures)

## Quick start

This is a basic `flake.nix` example:

```nix
{
  inputs = {
    nixpkgs.url = "github:nixOS/nixpkgs";
    comin = {
      url = "github:nlewo/comin";
      inputs.nixpkgs.follows = "nixpkgs";
    };
  };
  outputs = { self, nixpkgs, comin }: {
    nixosConfigurations = {
      myMachine = nixpkgs.lib.nixosSystem {
        system = "x86_64-linux";
        modules = [
          comin.nixosModules.comin
          ({
            services.comin = {
              enable = true;
              remotes = [{
                name = "origin";
                url = "https://gitlab.com/your/infra.git";
                branches.main.name = "main";
              }];
            };
          })
        ];
      };
    };
  };
}
```

This enables a systemd service, which periodically pulls the `main`
branch of the repository `https://gitlab.com/your/infra.git` and
deploys the NixOS configuration corresponding to the machine hostname
`myMachine`.

A new commit in the `main` branch of the repository
`https://gitlab.com/your/infra.git` is then deployed in the next 60
seconds.

Comin exposes much more options which are described in the [generated
documentation](https://github.com/nlewo/comin/blob/main/docs/generated-module-options.md).

## Documentation

- [Howtos](./docs/howtos.md)
- [Advanced Configuraion](./docs/advanced-config.md)
- [Authentication](./docs/authentication.md)
- [Comin module options](./docs/generated-module-options.md)
- [Design](./docs/design.md)
- [Contribute](./docs/contribute.md)

## Community

We have a Matrix room at [https://matrix.to/#/#nixos-comin:matrix.org](https://matrix.to/#/#nixos-comin:matrix.org).

